using EditorPrefs = MashBoxSDK.AnimationStudio.StudioPreferenceStore;
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using MashBoxSDK.AnimationStudio;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using Object=UnityEngine.Object;
public static class StudioBevelIntegrationValidation
{
 static int checks,cases;static string current="start";static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool p,string s){if(!p)throw new Exception(current+": "+s);checks++;}
 static object Call(object o,string n,params object[] args)=>o.GetType().GetMethod(n,F).Invoke(o,args);static void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);
 static (int,int) Key(int a,int b)=>a<b?(a,b):(b,a);
 static List<(int,int)> Edges(StudioMeshCuts t){var ids=new Dictionary<Vector3,int>();var seen=new HashSet<(int,int)>();var result=new List<(int,int)>();foreach(var f in t.Faces)for(int i=0;i<f.Vertices.Count;i++){int a=f.Vertices[i],b=f.Vertices[(i+1)%f.Vertices.Count];if(!ids.ContainsKey(t.Positions[a]))ids.Add(t.Positions[a],ids.Count);if(!ids.ContainsKey(t.Positions[b]))ids.Add(t.Positions[b],ids.Count);if(seen.Add(Key(ids[t.Positions[a]],ids[t.Positions[b]])))result.Add((a,b));}return result;}
 static StudioModelDocument.Node Cube(){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);var m=Object.Instantiate(o.GetComponent<MeshFilter>().sharedMesh);Object.DestroyImmediate(o);return new StudioModelDocument.Node{name="Bevel validation",mesh=m};}
 static StudioModelDocument.Node PolygonMesh(Vector3[] vertices,int[][] polygons)
 {var m=new Mesh();m.vertices=vertices;var tr=new List<int>();var data=new List<int>();foreach(var p in polygons){data.Add(0);data.Add(p.Length);data.AddRange(p);if(p.Length==6){foreach(var tri in new[]{new[]{0,1,3},new[]{1,2,3},new[]{0,3,5},new[]{3,4,5}})foreach(int i in tri)tr.Add(p[i]);}else for(int i=1;i<p.Length-1;i++){tr.Add(p[0]);tr.Add(p[i]);tr.Add(p[i+1]);}}m.triangles=tr.ToArray();m.RecalculateNormals();m.RecalculateBounds();return new StudioModelDocument.Node{name="Polygon test",mesh=m,cutPolygons=data.ToArray(),cutTriangles=m.triangles};}
 static StudioModelDocument.Node Prism(){var xy=new[]{new Vector2(0,0),new Vector2(2,0),new Vector2(2,1),new Vector2(1,1),new Vector2(1,2),new Vector2(0,2)};var v=new List<Vector3>();foreach(float z in new[]{-.5f,.5f})foreach(var p in xy)v.Add(new Vector3(p.x,p.y,z));var faces=new List<int[]>{new[]{5,4,3,2,1,0},new[]{6,7,8,9,10,11}};for(int i=0;i<6;i++)faces.Add(new[]{i,(i+1)%6,(i+1)%6+6,i+6});return PolygonMesh(v.ToArray(),faces.ToArray());}
 static void Validate(StudioModelDocument.Node n,bool closed=true)
 {var m=n.mesh;var v=m.vertices;var t=m.triangles;double eps=Math.Max(1e-30,Math.Pow(m.bounds.size.magnitude,4)*1e-20);var ids=new Dictionary<Vector3,int>();var uses=new Dictionary<(int,int),(int count,int a,int b)>();for(int i=0;i<t.Length;i+=3){Check(Vector3.Cross(v[t[i+1]]-v[t[i]],v[t[i+2]]-v[t[i]]).sqrMagnitude>eps,"Nondegenerate triangles");for(int j=0;j<3;j++){var p=v[t[i+j]];var q=v[t[i+(j+1)%3]];if(!ids.ContainsKey(p))ids.Add(p,ids.Count);if(!ids.ContainsKey(q))ids.Add(q,ids.Count);int a=ids[p],b=ids[q];var k=Key(a,b);if(uses.TryGetValue(k,out var u)){Check(u.count==1&&u.a==b,"Oriented manifold triangle edges");uses[k]=(2,u.a,u.b);}else uses.Add(k,(1,a,b));}}Check(!closed||uses.Values.All(u=>u.count==2),"No holes on closed mesh");Check(ids.Count-uses.Count+t.Length/3==(closed?2:1),"Euler topology preserved");Check(m.normals.Length==v.Length&&m.normals.All(p=>!float.IsNaN(p.x)&&p.sqrMagnitude>.98f),"Finite unit normals");Check(n.normalGroups.Length==v.Length,"Smoothing group stream retained");cases++;}
 public static void Run()
 {
  var live=new List<Mesh>();StudioModelEditor ed=null;StudioModelDocument doc=null;var pref=new Dictionary<string,(bool had,float val)>();
  try{
   foreach(var j in new[]{StudioMeshCuts.BevelJunction.Patch,StudioMeshCuts.BevelJunction.Uniform})
   {
    current="concave L prism "+j;var n=Prism();live.Add(n.mesh);var t=new StudioMeshCuts(n);t.BevelEdges(n,Edges(t),new StudioMeshCuts.BevelOptions{Width=.25f,Subdivisions=3,Tension=1,Junction=j});Validate(n);
    current="octahedron "+j;n=PolygonMesh(new[]{Vector3.right,Vector3.up,Vector3.forward,Vector3.left,Vector3.down,Vector3.back},new[]{new[]{0,1,2},new[]{2,1,3},new[]{3,1,5},new[]{5,1,0},new[]{2,4,0},new[]{3,4,2},new[]{5,4,3},new[]{0,4,5}});live.Add(n.mesh);t=new StudioMeshCuts(n);t.BevelEdges(n,Edges(t),new StudioMeshCuts.BevelOptions{Width=.3f,Subdivisions=4,Tension=.5f,Junction=j});Validate(n);
    current="open boundary corner "+j;n=PolygonMesh(new[]{new Vector3(-1,0,0),Vector3.zero,Vector3.up,new Vector3(-1,1,0),Vector3.forward,new Vector3(0,1,1)},new[]{new[]{0,1,2,3},new[]{2,1,4,5}});live.Add(n.mesh);t=new StudioMeshCuts(n);t.BevelEdges(n,new[]{(1,2)},new StudioMeshCuts.BevelOptions{Width=.25f,Subdivisions=3,Tension=1,Junction=j});Validate(n,false);
   }
   foreach(float size in new[]{.001f,.01f,100f,1000f}){current="scale "+size;var n=Cube();live.Add(n.mesh);var topology=new StudioMeshCuts(n);n.cutPolygons=topology.Faces.SelectMany(f=>new[]{f.Submesh,f.Vertices.Count}.Concat(f.Vertices)).ToArray();var v=n.mesh.vertices;for(int i=0;i<v.Length;i++)v[i]*=size;n.mesh.vertices=v;n.mesh.RecalculateBounds();n.cutTriangles=n.mesh.triangles;topology=new StudioMeshCuts(n);topology.BevelEdges(n,Edges(topology),new StudioMeshCuts.BevelOptions{Width=.2f,Subdivisions=3,Tension=1,Junction=StudioMeshCuts.BevelJunction.Uniform});Validate(n);}
   current="UV/color/material seams";var attributes=Cube();live.Add(attributes.mesh);var source=new StudioMeshCuts(attributes);var m=attributes.mesh;var oldVertices=m.vertices;var oldUV=m.uv;var col=Enumerable.Range(0,m.vertexCount).Select(i=>new Color(i/24f,(24-i)/24f,.5f,1)).ToArray();m.colors=col;
   for(int c=1;c<8;c++){if(c%3==0)m.SetUVs(c,Enumerable.Range(0,m.vertexCount).Select(i=>new Vector2(i/24f,c)).ToList());else if(c%3==1)m.SetUVs(c,Enumerable.Range(0,m.vertexCount).Select(i=>new Vector3(i/24f,c,i)).ToList());else m.SetUVs(c,Enumerable.Range(0,m.vertexCount).Select(i=>new Vector4(i/24f,c,i,1)).ToList());}
   m.subMeshCount=3;var sub=new List<int>[] {new List<int>(),new List<int>(),new List<int>()};for(int f=0;f<source.Faces.Count;f++){var p=source.Faces[f];p.Submesh=f%3;for(int i=1;i<p.Vertices.Count-1;i++)sub[p.Submesh].AddRange(new[]{p.Vertices[0],p.Vertices[i],p.Vertices[i+1]});}for(int s=0;s<3;s++)m.SetTriangles(sub[s],s);attributes.cutPolygons=source.Faces.SelectMany(f=>new[]{f.Submesh,f.Vertices.Count}.Concat(f.Vertices)).ToArray();attributes.cutTriangles=m.triangles;source=new StudioMeshCuts(attributes);var chosen=Edges(source)[0];source.BevelEdges(attributes,new[]{chosen},new StudioMeshCuts.BevelOptions{Width=.2f,Subdivisions=4,Tension=1,Junction=StudioMeshCuts.BevelJunction.Uniform});Validate(attributes);Check(m.subMeshCount==3&&Enumerable.Range(0,3).All(s=>m.GetTriangles(s).Length>0),"Material slots retained");for(int c=0;c<8;c++){var list=new List<Vector4>();m.GetUVs(c,list);Check(list.Count==m.vertexCount,"UV channel "+c+" retained");Check(m.GetVertexAttributeDimension((VertexAttribute)((int)VertexAttribute.TexCoord0+c))==(c==0||c%3==0?2:c%3==1?3:4),"UV dimensionality "+c+" retained");}Check(m.colors.Length==m.vertexCount&&m.tangents.Length==m.vertexCount,"Colors and regenerated tangents retained");
   for(int i=0;i<oldVertices.Length;i++){if(oldVertices[i]==oldVertices[chosen.Item1]||oldVertices[i]==oldVertices[chosen.Item2])continue;Check(Enumerable.Range(0,m.vertexCount).Any(v=>m.vertices[v]==oldVertices[i]&&m.uv[v]==oldUV[i]&&m.colors[v]==col[i]),"Unchanged source seam attributes retained");}
   current="atomic validation";var unchanged=Cube();live.Add(unchanged.mesh);var ct=new StudioMeshCuts(unchanged);var edge=Edges(ct)[0];foreach(float w in new[]{-1f,2f,float.NaN,float.PositiveInfinity}){bool before=false;var old=unchanged.mesh.vertices;try{ct.BevelEdges(unchanged,new[]{edge},new StudioMeshCuts.BevelOptions{Width=w},()=>before=true);throw new Exception("Invalid width accepted");}catch(InvalidOperationException){}Check(!before&&old.SequenceEqual(unchanged.mesh.vertices),"Invalid input is rejected before mutation");}
   var open=PolygonMesh(new[]{Vector3.zero,Vector3.right,Vector3.up},new[]{new[]{0,1,2}});live.Add(open.mesh);bool wrote=false;try{new StudioMeshCuts(open).BevelEdges(open,new[]{(0,1)},new StudioMeshCuts.BevelOptions{Width=.2f},()=>wrote=true);throw new Exception("Boundary edge accepted");}catch(InvalidOperationException){}Check(!wrote,"Boundary selection rejected atomically");
   current="editor, Undo, defaults and workspace";foreach(var name in new[]{"Width","Subdivisions","Tension","Junction"}){string key=ToolChannelPane.DefaultKey("Bevel Edges",name);pref[key]=(EditorPrefs.HasKey(key),ToolChannelPane.GetFloatDefault("Bevel Edges",name,0));}ToolChannelPane.SetFloatDefault("Bevel Edges","Width",.15f);ToolChannelPane.SetFloatDefault("Bevel Edges","Subdivisions",3);ToolChannelPane.SetFloatDefault("Bevel Edges","Tension",.75f);ToolChannelPane.SetFloatDefault("Bevel Edges","Junction",1);
   var node=Cube();live.Add(node.mesh);doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(node);doc.nodes.Add(new StudioModelDocument.Node{name="Shared mesh",mesh=node.mesh,position=Vector3.right*2});ed=new StudioModelEditor(()=>{});ed.Load(doc);ed.SelectObject(0);Set(ed,"mode",StudioModelEditor.ComponentMode.Edge);ed.Components.Add(0);var menu=new StudioMenu();Call(ed,"PopulateModelMenu","Mesh Tools",menu,null,null);var item=menu.Items.Single(i=>i.Text=="Bevel…");item.Action();Check(Resources.FindObjectsOfTypeAll<ToolChannelPane>().Any(p=>p.titleContent.text=="Bevel"),"Menu opens ToolChannelPane");int original=node.mesh.vertexCount;Call(ed,"ApplyBevelEdges");Check(node.mesh.vertexCount>original&&ed.Components.Count>0,"Editor bevel rebuilds and retains edge selection");Check(doc.nodes[0].cutPolygons.SequenceEqual(doc.nodes[1].cutPolygons)&&doc.nodes[0].normalGroups.SequenceEqual(doc.nodes[1].normalGroups),"Shared mesh nodes receive matching topology and smoothing");Validate(doc.nodes[0]);Undo.PerformUndo();Check(node.mesh.vertexCount==original,"Undo restores original mesh");Undo.PerformRedo();Check(node.mesh.vertexCount>original,"Redo restores bevel");Validate(doc.nodes[0]);
   Directory.CreateDirectory(StudioModelDocument.WorkspaceFolder);string path=Path.Combine(StudioModelDocument.WorkspaceFolder,"bevel-roundtrip-"+Guid.NewGuid().ToString("N")+".workspace");StudioWorkspaceText.Write(doc,path);var restored=StudioWorkspaceText.Read(path);try{Check(restored.nodes[0].normalGroups.SequenceEqual(doc.nodes[0].normalGroups),"Workspace persists bevel smoothing");Check(restored.nodes[0].cutPolygons.SequenceEqual(doc.nodes[0].cutPolygons),"Workspace persists bevel polygons");Validate(restored.nodes[0]);}finally{foreach(var mesh in restored.nodes.Select(n=>n.mesh).Where(n=>n).Distinct())Object.DestroyImmediate(mesh);Object.DestroyImmediate(restored);}
   ed.Load(null);Check(!Resources.FindObjectsOfTypeAll<ToolChannelPane>().Any(p=>p.titleContent.text=="Bevel"),"Workspace switch closes bevel pane");
   File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath, "../bevel-integration-result.txt")),"PASS "+checks+" checks across "+cases+" geometry/integration cases");
  }catch(Exception e){File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath, "../bevel-integration-result.txt")),current+"\n"+e);}finally{ed?.Dispose();Undo.ClearAll();foreach(var m in live)if(m)Object.DestroyImmediate(m);if(doc)Object.DestroyImmediate(doc);foreach(var p in pref){string name=p.Key.Substring(p.Key.LastIndexOf('.')+1);ToolChannelPane.SetFloatDefault("Bevel Edges",name,p.Value.val);}ToolChannelPane.FlushDefaults();foreach(var p in pref)if(!p.Value.had)EditorPrefs.DeleteKey(p.Key);EditorApplication.Exit(0);}
 }
}

